from pathlib import Path
import re

path = Path('ai-for-managers-dashboard/app/page.tsx')
s = path.read_text()
original = s

# Week 6 privacy decision tree: require six actual non-empty answers.
s = s.replace(
    "Object.keys(structuredAnswers).filter((key) => key.startsWith('privacy-')).length >= 6",
    "[0, 1, 2, 3, 4, 5].every((index) => Boolean(structuredAnswers[`privacy-${index}`]))",
)

# Week 6 BrightPath: progressively reveal facts, then require a final management recommendation and rationale.
brightpath_pattern = r"\{selectedItem\.type === 'case' && selectedWeek === 6 && <section.*?</section>\}"
brightpath = """{selectedItem.type === 'case' && selectedWeek === 6 && <section className=\"lmsPanel structuredLesson\"><div className=\"panelBar\"><h3>BrightPath Manufacturing · Decision Simulation</h3><span>Round {Number(structuredAnswers.brightpathRound || 1)} of 4</span></div><p>BrightPath wants to use AI to screen applicants. Start with the questions you need, then reveal one fact at a time and update your risk judgment.</p><div className=\"caseReveal\"><strong>ROUND 1 · WHAT DO YOU NEED TO KNOW?</strong><textarea value={String(structuredAnswers.brightpathQuestions || '')} onChange={(event) => answerStructured('brightpathQuestions', event.target.value)} placeholder=\"Purpose, data, affected people, error patterns, oversight, accountability...\" /></div>{Number(structuredAnswers.brightpathRound || 1) >= 2 && <div className=\"caseReveal\"><strong>ROUND 2 · HISTORICAL DATA</strong><p>The model was trained partly on historical hiring decisions from a workforce that was not demographically representative. Reassess representation, job-relatedness, and possible unequal outcomes.</p></div>}{Number(structuredAnswers.brightpathRound || 1) >= 3 && <div className=\"caseReveal\"><strong>ROUND 3 · VENDOR CLAIM</strong><p>The vendor reports 95% accuracy but does not provide the definition of accuracy, error distribution, fairness measures, or group-level results.</p></div>}{Number(structuredAnswers.brightpathRound || 1) >= 4 && <div className=\"caseReveal\"><strong>ROUND 4 · AUTOMATIC REJECTION</strong><p>Applicants scoring below 60 are automatically rejected before a recruiter reviews them. The vendor also processes applicant personal information outside BrightPath.</p><fieldset><legend>Final management recommendation</legend>{['Approve', 'Approve with safeguards', 'Pause pending evidence', 'Do not use'].map((choice) => <label className=\"choiceLabel\" key={choice}><input type=\"radio\" name=\"brightpath-final\" checked={structuredAnswers.brightpathDecision === choice} onChange={() => answerStructured('brightpathDecision', choice)} />{choice}</label>)}</fieldset><textarea value={String(structuredAnswers.brightpathRationale || '')} onChange={(event) => answerStructured('brightpathRationale', event.target.value)} placeholder=\"Explain the risk level, evidence, stakeholders, safeguards, accountable owner, human oversight, and what additional evidence you need.\" />{structuredAnswers.brightpathDecision && <div className=\"decisionFeedback\"><strong>Defend the decision, not just the label.</strong><p>A strong answer connects the historical data, missing vendor evidence, automatic rejection, personal-data handling, human review, accountability, and a clear condition for proceeding or stopping.</p></div>}</div>}<button className=\"primaryAction\" type=\"button\" disabled={Number(structuredAnswers.brightpathRound || 1) === 1 && !String(structuredAnswers.brightpathQuestions || '').trim()} onClick={() => answerStructured('brightpathRound', Math.min(4, Number(structuredAnswers.brightpathRound || 1) + 1))}>{Number(structuredAnswers.brightpathRound || 1) < 4 ? 'Reveal next round' : 'Case evidence fully revealed'}</button></section>}"""
s, count = re.subn(brightpath_pattern, brightpath, s, count=1)
if count != 1:
    raise RuntimeError('BrightPath block was not found exactly once')

# Week 7: each practice card now has its own activity rather than all opening the same generic simulation.
generic_w7_pattern = r"\{selectedItem\.type === 'practice' && selectedWeek === 7 && <section.*?</section>\}"
distinct_practices = """{selectedItem.type === 'practice' && selectedWeek === 7 && selectedItem.id === 'practice-roles' && <section className=\"lmsPanel structuredLesson\"><div className=\"panelBar\"><h3>Governance Role Activity</h3><span>GOVERN</span></div><p>Palmetto wants to use AI-assisted recruiting. Assign the people who approve the use, own the business decision, review data/security, monitor outcomes, handle incidents, and have stop authority.</p><div className=\"decisionTree\">{[['Executive sponsor','Approves organizational direction and escalation'],['Business owner','Owns the use case and outcome'],['IT / security','Reviews tool, access, and security controls'],['Legal / compliance','Reviews applicable obligations and policy'],['Monitoring owner','Tracks outcomes and control effectiveness'],['Stop authority','Can pause or stop the system']].map(([role, purpose]) => <label key={role}>{role}<input value={String(structuredAnswers[`role-${role}`] || '')} onChange={(event) => answerStructured(`role-${role}`, event.target.value)} placeholder={purpose} /></label>)}</div><div className=\"decisionFeedback\"><strong>Manager takeaway</strong><p>Governance is weak when responsibility is vague. High-impact AI needs named decision rights, escalation, and stop authority.</p></div></section>}
      {selectedItem.type === 'practice' && selectedWeek === 7 && selectedItem.id === 'practice-map' && <section className=\"lmsPanel structuredLesson\"><div className=\"panelBar\"><h3>Palmetto AI Use Case Map</h3><span>MAP</span></div><p>Map the proposed recruiting use before deciding whether it is appropriate.</p><div className=\"decisionTree\">{[['Purpose','What business problem is being solved?'],['Affected people','Who could benefit or be harmed?'],['Data','What personal, historical, or confidential data is involved?'],['Assumptions','What are we assuming about accuracy, fairness, or context?'],['Possible harm','What could go wrong and who bears the error?']].map(([label, placeholder]) => <label key={label}>{label}<textarea value={String(structuredAnswers[`map-${label}`] || '')} onChange={(event) => answerStructured(`map-${label}`, event.target.value)} placeholder={placeholder} /></label>)}</div><div className=\"decisionFeedback\"><strong>Feedback</strong><p>MAP should make the real use, stakeholders, data, assumptions, and harm pathways visible before controls are chosen.</p></div></section>}
      {selectedItem.type === 'practice' && selectedWeek === 7 && selectedItem.id === 'practice-deploy' && <section className=\"lmsPanel structuredLesson\"><div className=\"panelBar\"><h3>Before You Deploy</h3><span>MEASURE</span></div><p>Decide whether Palmetto has enough evidence to move forward.</p><div className=\"checklistGrid\">{['Purpose and intended use documented','Data quality and provenance evaluated','Relevant performance tested','Fairness and privacy evaluated','Qualified human review established','Limitations documented','Monitoring and incident plan ready','Stop conditions defined'].map((item) => <label key={item}><input type=\"checkbox\" checked={Boolean(structuredAnswers[`deploy-${item}`])} onChange={() => answerStructured(`deploy-${item}`, !structuredAnswers[`deploy-${item}`])} />{item}</label>)}</div><div className=\"choiceRow\">{['READY','NEEDS SAFEGUARDS / TESTING','NOT READY'].map((choice) => <button className={structuredAnswers.deployDecision === choice ? 'selected' : ''} type=\"button\" onClick={() => answerStructured('deployDecision', choice)} key={choice}>{choice}</button>)}</div>{structuredAnswers.deployDecision && <div className=\"decisionFeedback\"><strong>{Object.keys(structuredAnswers).filter((key) => key.startsWith('deploy-') && structuredAnswers[key] === true).length >= 7 && structuredAnswers.deployDecision === 'READY' ? 'The evidence checklist supports readiness.' : structuredAnswers.deployDecision === 'READY' ? 'Reconsider READY: important evidence or controls are still unchecked.' : 'A cautious deployment decision is appropriate when evidence is incomplete.'}</strong><p>MEASURE is about evidence tied to the actual risk, not confidence in the vendor.</p></div>}</section>}
      {selectedItem.type === 'practice' && selectedWeek === 7 && selectedItem.id === 'practice-treatment' && <section className=\"lmsPanel structuredLesson\"><div className=\"panelBar\"><h3>Risk Treatment Activity</h3><span>MANAGE</span></div><p>Applicant outcomes differ sharply across groups and the cause is not yet understood. What should Palmetto do?</p><div className=\"choiceStack\">{['Accept','Reduce','Transfer','Avoid','Escalate'].map((choice) => <button className={structuredAnswers.treatmentDecision === choice ? 'selected' : ''} type=\"button\" onClick={() => answerStructured('treatmentDecision', choice)} key={choice}>{choice}</button>)}</div>{structuredAnswers.treatmentDecision && <div className=\"decisionFeedback\"><strong>{structuredAnswers.treatmentDecision === 'Reduce' || structuredAnswers.treatmentDecision === 'Escalate' ? 'Defensible treatment.' : 'Reconsider the fit between the evidence and the treatment.'}</strong><p>When a consequential system shows unexplained group differences, a manager should not simply accept the risk. Pause automatic action, investigate causes, add controls, and escalate when authority or evidence is insufficient.</p></div>}</section>}
      {selectedItem.type === 'practice' && selectedWeek === 7 && selectedItem.id === 'practice-data' && <section className=\"lmsPanel structuredLesson\"><div className=\"panelBar\"><h3>Data Governance Decision</h3><span>Week 6 → Week 7</span></div><p>Week 6 identified a privacy concern: personal applicant data may be processed by an outside AI vendor. Turn that concern into governance controls.</p><div className=\"checklistGrid\">{['Purpose limitation','Approved access','Data minimization','Retention rule','Vendor handling requirements','Security controls','Documented authorization','Incident route'].map((control) => <label key={control}><input type=\"checkbox\" checked={Boolean(structuredAnswers[`data-${control}`])} onChange={() => answerStructured(`data-${control}`, !structuredAnswers[`data-${control}`])} />{control}</label>)}</div><textarea value={String(structuredAnswers.dataOwner || '')} onChange={(event) => answerStructured('dataOwner', event.target.value)} placeholder=\"Who owns this control and how will it be monitored?\" /><div className=\"decisionFeedback\"><strong>Connection</strong><p>Privacy risk becomes governance when the organization assigns a control, owner, evidence requirement, and review process.</p></div></section>}"""
s, count = re.subn(generic_w7_pattern, distinct_practices, s, count=1)
if count != 1:
    raise RuntimeError('Generic Week 7 practice block was not found exactly once')

# Week 7 maturity feedback must depend on the student's diagnosis.
s = s.replace(
    '<strong>Feedback</strong><p>Palmetto is closest to Level 1, Ad hoc. A reasonable next aim is Level 3, Managed: establish roles, policy, training, controls, and an incident route before claiming mature measurement.</p>',
    "<strong>{structuredAnswers.maturityCurrent === '1 · Ad hoc' ? 'Correct diagnosis.' : 'Reconsider the current level.'}</strong><p>Given scattered use, no central owner, only a draft policy, and no monitoring or incident route, Palmetto is closest to Level 1 · Ad hoc. A reasonable next aim is Level 3 · Managed: establish roles, policy, training, controls, and an incident route before claiming mature measurement.</p>",
)

# Week 7 capstone: reveal use-case-specific governance guidance and require controls/owners/monitoring.
capstone_pattern = r"\{selectedItem\.type === 'assessment' && selectedWeek === 7 && selectedItem\.id === 'assessment-capstone' && <section.*?</section>\}"
capstone = """{selectedItem.type === 'assessment' && selectedWeek === 7 && selectedItem.id === 'assessment-capstone' && <section className=\"lmsPanel structuredLesson\"><div className=\"panelBar\"><h3>You Are the AI Governance Manager</h3><span>Weeks 6 + 7 capstone</span></div><p>Classify each Palmetto use, then compare your choice with the risk profile and required controls.</p><div className=\"decisionTree\">{[['AI-assisted recruiting','High-impact employment use: additional approval, qualified human review, fairness testing, data restrictions, documentation, and monitoring are expected.'],['Customer service chatbot','Usually lower impact, but needs disclosure, verification, privacy controls, escalation for sensitive issues, and monitoring.'],['Personalized marketing','Requires attention to authorization, data minimization, profiling risk, transparency, and monitoring.'],['Employee productivity analysis','High people-impact use: investigate measurement validity, privacy, fairness, worker impact, review authority, and limits on automated action.']].map(([useCase, guidance]) => <label key={useCase}>{useCase}<select value={String(structuredAnswers[`capstone-${useCase}`] || '')} onChange={(event) => answerStructured(`capstone-${useCase}`, event.target.value)}><option value=\"\">Classify</option><option>Approved</option><option>Approved with safeguards</option><option>Requires additional review</option><option>Prohibited</option></select>{structuredAnswers[`capstone-${useCase}`] && <small>{guidance}</small>}</label>)}</div><textarea value={String(structuredAnswers.capstoneControls || '')} onChange={(event) => answerStructured('capstoneControls', event.target.value)} placeholder=\"For at least two use cases, name the safeguard, owner, monitoring requirement, and policy section that supports your decision.\" /><div className=\"decisionFeedback\"><strong>Final connection</strong><p>Week 6 asks what could go wrong. Week 7 requires an owner, control, policy rule, evidence, monitoring, and an incident or escalation path for those risks.</p></div></section>}"""
s, count = re.subn(capstone_pattern, capstone, s, count=1)
if count != 1:
    raise RuntimeError('Week 7 capstone block was not found exactly once')

# Focus build screens on the actual artifact instead of repeating the whole week inside the build.
policy_field = "  const policyField = (field: PolicyEditableKey, label: string, placeholder: string) => <label key={field}>{label}{field === 'organization' || field === 'reviewSchedule' ? <input value={String(policyDraft[field])} onChange={(event) => updatePolicy(field, event.target.value)} placeholder={placeholder} /> : <textarea value={String(policyDraft[field])} onChange={(event) => updatePolicy(field, event.target.value)} placeholder={placeholder} />}</label>;\n\n"
helpers = """  const renderEthicsBuildOnly = () => <>
    <section className=\"lmsPanel buildPanel\"><div className=\"panelBar\"><h3>AI Ethics Checker</h3><span>{ethicsAssessment.complete ? 'Complete' : 'In progress'}</span></div><p><strong>BUSI 610 Educational AI Risk Assessment.</strong> This is an instructional decision-support tool, not an official NIST assessment, legal determination, compliance certification, or substitute for professional review.</p><div className=\"assessmentFields\">{ethicsField('useCase', '1. What is the AI being used for?')}{ethicsField('personalData', '2. Personal or sensitive information?')}{ethicsField('disadvantage', '3. Could it disadvantage a person or group?')}{ethicsField('harm', '4. Could an incorrect decision cause significant harm?')}{ethicsField('humanReview', '5. Can a qualified human review and override the recommendation?')}{ethicsField('explainability', '6. Can the organization explain the result?')}{ethicsField('challenge', '7. Can the decision be challenged or overturned?')}{ethicsField('dataFit', '8. Is the data appropriate for the purpose?')}{ethicsField('accountable', '9. Does the organization know who is accountable?')}{ethicsField('risk', '10. Overall educational risk rating')}{ethicsField('recommendation', '11. Management recommendation')}{ethicsField('rationale', '12. Explain the decision, evidence, safeguards, and remaining uncertainty.')}</div><div className=\"riskAssessmentGrid\">{ethicsRiskCategories.map((category) => <label key={category}>{category}<select value={ethicsAssessment.categoryRisks[category] || ''} onChange={(event) => updateEthicsCategory(category, event.target.value)}><option value=\"\">Choose</option><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>UNKNOWN</option></select></label>)}</div><div className=\"decisionFeedback\"><strong>Main risk factors:</strong> {Object.entries(ethicsAssessment.categoryRisks).filter(([, value]) => value === 'HIGH').map(([key]) => key).join(', ') || 'No high-risk category selected yet.'}<br /><strong>Missing evidence:</strong> {ethicsAssessment.challenge || 'Identify what information is still missing before deciding.'}<br /><strong>Safeguards:</strong> {ethicsAssessment.humanReview === 'No' || ethicsAssessment.humanReview === 'Not currently' ? 'Add qualified human review and override authority; restrict unnecessary data; verify outputs; document monitoring.' : 'Maintain qualified review, verify outputs, document decisions, and reassess as the use changes.'}<br /><strong>Management action:</strong> {ethicsAssessment.recommendation || 'Choose an action before finalizing.'}</div><div className=\"formActions\"><button type=\"button\" onClick={() => saveBuild('ethics')}>{saveNotice || 'Save as draft'}</button><button type=\"button\" onClick={resetEthics}>Reset</button><button className=\"primaryAction\" type=\"button\" onClick={() => markBuildComplete('ethics')}>Submit / mark complete</button></div></section>
    <section className=\"lmsPanel lessonGrid\"><div className=\"panelBar\"><h3>Test the checker</h3><span>Before completion</span></div><ol><li>Run BrightPath through the checker.</li><li>Confirm the rating follows the evidence rather than the vendor&apos;s confidence.</li><li>Confirm the recommendation names safeguards, accountability, and what evidence could change the decision.</li><li>Save, leave the module, return, and confirm the assessment persists.</li></ol></section>
  </>;

  const renderPolicyBuildOnly = () => <>
    <section className=\"lmsPanel buildPanel\"><div className=\"panelBar\"><h3>Stage 2 · Responsible AI Policy Builder</h3><span>{policyDraft.complete ? 'Complete' : policyDraft.organization ? 'In progress' : 'Not started'} · {policyDraft.version}</span></div><p>Translate the Stage 1 management decision into operational policy language. A strong policy says who acts, what is allowed or prohibited, what evidence is required, when review occurs, and what happens when a control fails.</p><div className=\"policyMeta\"><label>Organization name<input value={policyDraft.organization} onChange={(event) => updatePolicy('organization', event.target.value)} placeholder=\"Example: Palmetto Retail Group\" /></label><label>Industry<input value={policyDraft.industry} onChange={(event) => updatePolicy('industry', event.target.value)} placeholder=\"Retail, manufacturing, healthcare, etc.\" /></label><label>Policy owner<input value={policyDraft.policyOwner} onChange={(event) => updatePolicy('policyOwner', event.target.value)} placeholder=\"Role responsible for this policy\" /></label><label>Effective date<input type=\"date\" value={policyDraft.effectiveDate} onChange={(event) => updatePolicy('effectiveDate', event.target.value)} /></label><label>Review date<input type=\"date\" value={policyDraft.reviewDate} onChange={(event) => updatePolicy('reviewDate', event.target.value)} /></label><label>Policy status<select value={policyDraft.status} onChange={(event) => updatePolicy('status', event.target.value)}><option>Draft</option><option>Under review</option><option>Approved for class simulation</option></select></label></div><div className=\"assessmentFields policyFields\">{policySections.map(([field, label]) => policyField(field as PolicyEditableKey, label, 'Write a clear, organization-specific rule.'))}</div><div className=\"formActions\"><button type=\"button\" onClick={() => saveBuild('policy')}>{saveNotice || 'Save draft'}</button><button type=\"button\" onClick={savePolicyVersion}>Save version</button><button type=\"button\" onClick={resetPolicy}>Reset</button><button className=\"primaryAction\" type=\"button\" onClick={() => markBuildComplete('policy')}>Mark complete</button></div></section>
    <section className=\"lmsPanel readinessPanel\"><div className=\"panelBar\"><h3>Educational Policy Readiness Check</h3><span>{Object.values(policyDraft.readinessChecks).filter(Boolean).length} of 10</span></div><p>This educational readiness check identifies policy elements that may be missing. It is not a compliance score or legal determination.</p><div className=\"checklistGrid\">{['Approved uses', 'Prohibited uses', 'High-risk uses', 'Confidential information rules', 'Human review', 'Verification', 'Accountability', 'Incident reporting', 'Policy owner and review date', 'Monitoring'].map((item) => <label key={item}><input type=\"checkbox\" checked={Boolean(policyDraft.readinessChecks[item])} onChange={() => updatePolicyReadiness(item)} />{item}</label>)}</div></section>
    <section className=\"lmsPanel lessonGrid\"><div className=\"panelBar\"><h3>Bad policy vs. operational policy</h3><span>Quality check</span></div><div className=\"comparisonTable\"><article><strong>Weak</strong><p>“Employees should use AI responsibly.”</p></article><article><strong>Operational</strong><p>Approved tools may be used for non-confidential drafting. Consequential decisions require qualified human review. Sensitive information may not enter unapproved tools. Significant errors, privacy incidents, and discriminatory outcomes must be reported to the designated governance owner.</p></article></div></section>
  </>;

"""
if 'const renderEthicsBuildOnly' not in s:
    if policy_field not in s:
        raise RuntimeError('Policy field insertion point not found')
    s = s.replace(policy_field, policy_field + helpers)

s = s.replace(
    '</section>{selectedWeek === 6 ? renderEthicsModule() : renderGovernanceModule()}</>}',
    '</section>{selectedWeek === 6 ? renderEthicsBuildOnly() : renderPolicyBuildOnly()}</>}',
)

# Week 6/7 module-home workload should reflect the actual item estimates instead of a generic template.
s = s.replace(
    "{[['Learn', '2 hrs'], ['Practice', '1 hr'], ['Apply', '1 hr'], ['Build', '2–3 hrs'], ['Assess', '45 min'], ['Reflect', '30 min']].map",
    "{(selectedWeek === 6 ? [['Learn', '1.5–2 hrs'], ['Practice', '45–60 min'], ['Apply', '35–50 min'], ['Build', '45–75 min'], ['Assess', '45–65 min'], ['Reflect', '15–20 min']] : [['Learn', '2–2.5 hrs'], ['Practice', '1–1.5 hrs'], ['Apply', '30–45 min'], ['Build', '60–90 min'], ['Assess', '55–80 min'], ['Reflect', '15–20 min']]).map",
)

# Prevent artifact completion when core fields have not actually been completed.
s = s.replace(
    "function markBuildComplete(kind: 'ethics' | 'policy') {\n    if (kind === 'ethics') {",
    "function markBuildComplete(kind: 'ethics' | 'policy') {\n    if (kind === 'ethics') {\n      const requiredEthics = [ethicsAssessment.useCase, ethicsAssessment.personalData, ethicsAssessment.disadvantage, ethicsAssessment.harm, ethicsAssessment.humanReview, ethicsAssessment.explainability, ethicsAssessment.challenge, ethicsAssessment.dataFit, ethicsAssessment.accountable, ethicsAssessment.risk, ethicsAssessment.recommendation, ethicsAssessment.rationale];\n      if (requiredEthics.some((value) => !String(value).trim())) { setSaveNotice('Complete all Ethics Checker fields before marking it complete.'); window.setTimeout(() => setSaveNotice(''), 2600); return; }",
)
s = s.replace(
    "    } else {\n      setPolicyDraft((current) => ({ ...current, complete: true }));",
    "    } else {\n      const requiredPolicy = [policyDraft.organization, policyDraft.policyOwner, policyDraft.purpose, policyDraft.scope, policyDraft.approved, policyDraft.prohibited, policyDraft.humanReview, policyDraft.verification, policyDraft.accountability, policyDraft.incidents, policyDraft.monitoring];\n      const safeguardCount = ['Human review', 'Verification', 'Documentation', 'Data restrictions', 'Bias/fairness evaluation', 'Disclosure', 'Ongoing monitoring', 'Executive approval'].filter((item) => structuredAnswers[`safeguard-${item}`]).length;\n      if (!structuredAnswers.policyClass || safeguardCount === 0 || requiredPolicy.some((value) => !String(value).trim())) { setSaveNotice('Classify the use, select safeguards, and complete the core policy sections before marking it complete.'); window.setTimeout(() => setSaveNotice(''), 3000); return; }\n      setPolicyDraft((current) => ({ ...current, complete: true }));",
)

if s == original:
    raise RuntimeError('Cleanup script made no changes')

# Guardrails: do not intentionally alter content outside the Week 6/7 implementation regions.
for required in [
    "selectedItem.id === 'practice-roles'",
    "selectedItem.id === 'practice-map'",
    "selectedItem.id === 'practice-deploy'",
    "selectedItem.id === 'practice-treatment'",
    "selectedItem.id === 'practice-data'",
    'renderEthicsBuildOnly',
    'renderPolicyBuildOnly',
    'brightpathDecision',
    'Correct diagnosis.',
]:
    if required not in s:
        raise RuntimeError(f'Missing expected cleanup marker: {required}')

path.write_text(s)
print('Week 6/7 cleanup applied successfully')
